import{_ as e,o as a,c as d,a5 as l}from"./chunks/framework.DGp912Ge.js";const f=JSON.parse('{"title":"Gait & Status Reference","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/ros/reference.md","filePath":"ko/software/sdk/ros/reference.md","lastUpdated":1785213527000}'),o={name:"ko/software/sdk/ros/reference.md"};function s(i,t,c,n,r,g){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="gait-status-reference" tabindex="-1">Gait &amp; Status Reference <a class="header-anchor" href="#gait-status-reference" aria-label="Permalink to &quot;Gait &amp; Status Reference&quot;">​</a></h1><p>ROS 2 topic과 SDK에서 사용하는 Gait ID 및 <code>rbq_msgs/RobotStatus</code> 필드의 전체 레퍼런스입니다.</p><hr><h2 id="gait-state-id" tabindex="-1">Gait State ID <a class="header-anchor" href="#gait-state-id" aria-label="Permalink to &quot;Gait State ID&quot;">​</a></h2><p><code>/rbq/cmd/switch_gait</code> (Sub) 또는 <code>rbq_msgs/HighLevelCommand</code>의 <code>gait_state</code> 필드로 전환하고, 현재 값은 <code>/rbq/robot_status</code> → <code>gait_id</code> (Pub)로 확인합니다. 명령과 상태는 <strong>하나의</strong> gait enum을 공유하므로, 아래 id는 <code>HighLevelCommand.gait_state</code>로 보낼 때와 <code>robot_status.gait_id</code>로 읽을 때 모두 같은 의미입니다.</p><h3 id="표준-gait" tabindex="-1">표준 Gait <a class="header-anchor" href="#표준-gait" aria-label="Permalink to &quot;표준 Gait&quot;">​</a></h3><p><code>HighLevelCommand.gait_state</code> / <code>switch_gait</code>으로 보내며, <code>robot_status.gait_id</code>로 그대로 보고됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:center;">ID</th><th style="text-align:left;">상수</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:center;"><code>-3</code></td><td style="text-align:left;">—</td><td style="text-align:left;">Fall Recovery — 낙상 후 자동 복구 시도</td></tr><tr><td style="text-align:center;"><code>-2</code></td><td style="text-align:left;"><code>STATE_FALL</code></td><td style="text-align:left;">Fall Mode — 예기치 않은 균형 상실로 트리거</td></tr><tr><td style="text-align:center;"><code>-1</code></td><td style="text-align:left;"><code>STATE_OFF</code></td><td style="text-align:left;">Control Off — 모든 액추에이터 비활성</td></tr><tr><td style="text-align:center;"><code>0</code></td><td style="text-align:left;"><code>STATE_SIT</code></td><td style="text-align:left;">Sitting — 낮은 자세, 지면에 착지</td></tr><tr><td style="text-align:center;"><code>1</code></td><td style="text-align:left;"><code>STATE_STAND</code></td><td style="text-align:left;">Standing — 중립 자세, 보행 준비</td></tr><tr><td style="text-align:center;"><code>3</code></td><td style="text-align:left;"><code>STATE_WALK</code></td><td style="text-align:left;">Walk Mode — 트롯 보행</td></tr><tr><td style="text-align:center;"><code>4</code></td><td style="text-align:left;"><code>STATE_STAIRS</code></td><td style="text-align:left;">Stairs Mode — 카메라 센서를 사용하는 계단 적응 보행</td></tr><tr><td style="text-align:center;"><code>5</code></td><td style="text-align:left;"><code>STATE_WAVE</code></td><td style="text-align:left;">Wave Mode — 웨이브 보행</td></tr><tr><td style="text-align:center;"><code>10</code></td><td style="text-align:left;">—</td><td style="text-align:left;">Docking — 자동 도킹 시퀀스</td></tr></tbody></table><blockquote><p><code>-3</code>과 <code>10</code>은 <code>HighLevelCommand.msg</code>에 <code>STATE_*</code> 상수가 없습니다. <code>gait_state</code>에 숫자를 직접 지정하세요.</p></blockquote><h3 id="rl-gait" tabindex="-1">RL Gait <a class="header-anchor" href="#rl-gait" aria-label="Permalink to &quot;RL Gait&quot;">​</a></h3><p>학습된 보행 정책을 사용하는 Gait입니다 (ONNX 추론, <code>RLWalk</code> 프로세스 필요).</p><table tabindex="0"><thead><tr><th style="text-align:center;">ID</th><th style="text-align:left;">상수</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:center;"><code>48</code></td><td style="text-align:left;">—</td><td style="text-align:left;">RL Walk (Vision) — 비전 기반 지형 적응 학습 보행</td></tr><tr><td style="text-align:center;"><code>49</code></td><td style="text-align:left;">—</td><td style="text-align:left;">RL Walk — 학습 기반 보행</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">RL Gait 지정 방법</p><p><code>HighLevelCommand.msg</code>에 두 ID에 대응하는 이름 상수가 아직 정의되어 있지 않습니다. <code>gait_state</code>에 숫자를 직접 지정하세요 (예: <code>gait_state: 49</code>). 또한 정책 파일이 로드되어 있고 <code>RLWalk</code> 프로세스가 실행 중이어야 합니다. 로봇 구성에 따라 사용 가능한 id가 다를 수 있습니다.</p></div><hr><h2 id="로봇-상태-필드-rbq-robot-status" tabindex="-1">로봇 상태 필드 (<code>/rbq/robot_status</code>) <a class="header-anchor" href="#로봇-상태-필드-rbq-robot-status" aria-label="Permalink to &quot;로봇 상태 필드 (`/rbq/robot_status`)&quot;">​</a></h2><p><code>rbq_msgs/RobotStatus</code> 타입으로 <code>/rbq/robot_status</code>에 발행됩니다 (Pub, ~500 Hz). 아래 항목은 모두 메시지의 평면(flat) 필드입니다.</p><h3 id="상태-플래그-bool" tabindex="-1">상태 플래그 (<code>bool</code>) <a class="header-anchor" href="#상태-플래그-bool" aria-label="Permalink to &quot;상태 플래그 (`bool`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">ROS 필드명</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>con_start</code></td><td style="text-align:left;">모터 제어 루프 실행 중</td></tr><tr><td style="text-align:left;"><code>ready_pos</code></td><td style="text-align:left;">준비 자세 도달</td></tr><tr><td style="text-align:left;"><code>ground_pos</code></td><td style="text-align:left;">지면/앉기 자세</td></tr><tr><td style="text-align:left;"><code>force_con</code></td><td style="text-align:left;">힘 제어 모드 활성</td></tr><tr><td style="text-align:left;"><code>ext_joy</code></td><td style="text-align:left;">외부 조이스틱 입력 활성</td></tr><tr><td style="text-align:left;"><code>is_standing</code></td><td style="text-align:left;">로봇이 서 있음</td></tr><tr><td style="text-align:left;"><code>can_check</code></td><td style="text-align:left;">전체 관절 CAN 통신 확인 완료</td></tr><tr><td style="text-align:left;"><code>find_home</code></td><td style="text-align:left;">전체 관절 엔코더 홈 탐색 완료</td></tr></tbody></table><h3 id="gait-도킹" tabindex="-1">Gait &amp; 도킹 <a class="header-anchor" href="#gait-도킹" aria-label="Permalink to &quot;Gait &amp; 도킹&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">ROS 필드명</th><th style="text-align:left;">타입</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>gait_id</code></td><td style="text-align:left;"><code>int8</code></td><td style="text-align:left;">현재 활성 Gait (<a href="#gait-state-id">Gait State ID</a> 참조)</td></tr><tr><td style="text-align:left;"><code>docking_state</code></td><td style="text-align:left;"><code>int8</code></td><td style="text-align:left;">도킹 시퀀스 상태 (<a href="/RBQ/ko/software/sdk/ros/topics.html#로봇-상태">토픽 레퍼런스</a>의 도킹 상태 표 참조)</td></tr></tbody></table><h3 id="시스템-플래그-bool" tabindex="-1">시스템 플래그 (<code>bool</code>) <a class="header-anchor" href="#시스템-플래그-bool" aria-label="Permalink to &quot;시스템 플래그 (`bool`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">ROS 필드명</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><code>is_fall</code></td><td style="text-align:left;">낙하 감지됨</td></tr><tr><td style="text-align:left;"><code>imu_success</code></td><td style="text-align:left;">IMU 연결·데이터 정상</td></tr></tbody></table><hr><h2 id="초기화-시퀀스-확인" tabindex="-1">초기화 시퀀스 확인 <a class="header-anchor" href="#초기화-시퀀스-확인" aria-label="Permalink to &quot;초기화 시퀀스 확인&quot;">​</a></h2><p><code>/rbq/cmd/auto_start</code>를 발행한 후 아래 순서로 플래그가 올라옵니다:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>can_check  → true   (CAN 통신 확인)</span></span>\n<span class="line"><span>find_home  → true   (엔코더 홈 탐색 완료)</span></span>\n<span class="line"><span>con_start  → true   (제어 루프 시작)</span></span>\n<span class="line"><span>gait_id    → 0      (STATE_SIT — 명령 수신 가능)</span></span></code></pre></div><p>세 플래그가 모두 <code>true</code>가 된 후 Gait 전환 및 이동 명령을 보낼 수 있습니다.</p>',27)])])}const x=e(o,[["render",s]]);export{f as __pageData,x as default};
